const $=id=>document.getElementById(id);let number='',weapon='',version=0,catalog=[],vehicle=null,onlyFav=false,favs=new Set();let storageOK=true;try{const saved=JSON.parse(localStorage.getItem('entorno-favs')||'[]');if(Array.isArray(saved))favs=new Set(saved.filter(x=>typeof x==='string'));}catch{storageOK=false}
