options('situation',situations.map(x=>x[0]));const places=['en una tienda','en una gasolinera','en un banco','en una joyería','en la calle','en un callejón','en un aparcamiento','en un taller','en un bar','en un restaurante','en una vivienda','en una nave industrial','en el puerto','en el aeropuerto','en la playa','en la autopista','cerca del hospital','cerca de comisaría','en un motel','en un supermercado','en una armería','en un concesionario','en una plaza','en un garaje','en una zona rural','en un camping','en una obra','en una estación de tren','en un club nocturno','en un almacén'];options('place',places);
const clothes=['ropa de calle','sudadera y pantalón largo','chándal','traje','chaqueta y vaqueros','camiseta y vaqueros','camiseta y pantalón corto','ropa deportiva','ropa de motorista','mono de trabajo','ropa táctica','ropa de camuflaje','abrigo largo','chaleco y pantalón largo','camisa y pantalón','ropa de playa','uniforme de seguridad','ropa de repartidor','ropa de mecánico','ropa elegante','ropa ancha','ropa diferente entre sí','no se distingue'];options('clothing',clothes);options('clothcolor',colors);options('carcolor',colors);$('carcolor').value='2';const faces=['sin detalle visible','con pasamontañas','con la cara cubierta por una máscara','con un pañuelo tapando la cara','con casco integral','con gorra','con capucha puesta','con gafas de sol','con sombrero','con casco de moto abierto','con máscara de payaso','con máscara de animal','con gorro de lana','con mochila','con bolsa de deporte'];options('face',faces);options('finish',['sin especificar','mate','metalizado','cromado','perlado']);
const detailTexts=['Se oyen gritos.','Se oyen disparos.','Hay una persona en el suelo.','Se ve sangre en el suelo.','Hay cristales rotos.','El vehículo tiene los cristales tintados.','El vehículo tiene golpes visibles.','El motor sigue encendido.','Las puertas del vehículo están abiertas.','Se ha oído una alarma.','Hay humo en la zona.','Hay fuego visible.','Una persona lleva una bolsa.','Se ven guantes.','La matrícula no se distingue.','Hay gente corriendo.','Se han subido al vehículo.','El vehículo se ha marchado.'];detailTexts.forEach((text,i)=>{const l=document.createElement('label');l.className='check';const c=document.createElement('input');c.type='checkbox';c.value=text;c.id='detail'+i;l.append(c,document.createTextNode(text));$('details').append(l)});
function chips(id,items,current,callback){$(id).replaceChildren(...items.map(value=>{const b=document.createElement('button');b.type='button';b.textContent=value;b.setAttribute('aria-pressed',String(value===current));b.onclick=()=>{callback(value);chips(id,items,value,callback);generate()};return b}));}chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);
const categories={COMPACT:'Compactos',SEDAN:'Sedanes',SUV:'SUV',COUPE:'Cupés',MUSCLE:'Muscle',SPORT_CLASSIC:'Clásicos deportivos',SPORT:'Deportivos',SUPER:'Superdeportivos',MOTORCYCLE:'Motos',OFF_ROAD:'Todoterreno',INDUSTRIAL:'Industriales',UTILITY:'Utilitarios',VAN:'Furgonetas',CYCLE:'Bicicletas',BOAT:'Barcos',HELICOPTER:'Helicópteros',PLANE:'Aviones',SERVICE:'Servicios',EMERGENCY:'Emergencias',MILITARY:'Militares',COMMERCIAL:'Comerciales',RAIL:'Trenes',OPEN_WHEEL:'Monoplazas'};
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function filtered(){const q=norm($('search').value);return catalog.filter(c=>(!onlyFav||favs.has(c.id))&&(!$('category').value||c.category===$('category').value)&&norm(c.name+' '+c.brand+' '+c.id).includes(q))}
function renderCars(){const rows=filtered();$('cars').replaceChildren();rows.forEach(c=>{const row=document.createElement('div');row.className='vehicle'+(vehicle?.id===c.id?' selected':'');const b=document.createElement('button');b.type='button';b.className='choose';b.setAttribute('aria-pressed',String(vehicle?.id===c.id));b.append(document.createTextNode(c.name));const small=document.createElement('small');small.textContent=[c.brand,c.id,categories[c.category]||c.category].filter(Boolean).join(' · ');b.append(small);b.onclick=()=>{vehicle=c;renderCars();generate()};const star=document.createElement('button');star.type='button';star.className='star';star.textContent=favs.has(c.id)?'★':'☆';star.setAttribute('aria-label',(favs.has(c.id)?'Quitar de':'Añadir a')+' favoritos: '+c.name);star.setAttribute('aria-pressed',String(favs.has(c.id)));star.onclick=()=>{favs.has(c.id)?favs.delete(c.id):favs.add(c.id);try{localStorage.setItem('entorno-favs',JSON.stringify([...favs]));storageOK=true}catch{storageOK=false}renderCars()};row.append(b,star);$('cars').append(row)});if(!rows.length)$('cars').textContent=onlyFav?'No hay favoritos con estos filtros. Marca ☆ junto a un vehículo.':'No se han encontrado vehículos. Prueba otro nombre.';$('selected').textContent='Seleccionado: '+(vehicle?vehicle.name:'ninguno');$('catalogstatus').textContent=rows.length+' de '+catalog.length+' modelos · '+favs.size+' favoritos'+(!storageOK?' · No se pueden guardar los favoritos en este navegador.':'');}
$('search').oninput=renderCars;$('category').onchange=renderCars;$('favfilter').onclick=()=>{onlyFav=!onlyFav;$('favfilter').setAttribute('aria-pressed',String(onlyFav));$('favfilter').textContent=onlyFav?'★ Solo favoritos':'☆ Favoritos';renderCars()};
const selectedText=id=>$(id).selectedOptions[0].textContent;const pick=a=>a[version%a.length];function generate(){
if($('situation').value===''){ $('output').textContent='';count();return; }
const brief=$('length').value==='brief',one=number==='1',qty=number?(one?'una persona':number==='Más de 6'?'más de seis personas':number+' personas'):'alguien';const action=situations[+$('situation').value][brief?0:one||!number?1:2];const place=$('place').value===''?'':places[+$('place').value];let parts=[brief?qty.charAt(0).toUpperCase()+qty.slice(1)+' '+action+(place?' '+place:'')+'.':'Veo a '+qty+(place?' '+place:'')+'; '+action+'.'];const clothing=$('clothing').value===''?'':selectedText('clothing'),color=$('clothcolor').value===''?'':selectedText('clothcolor');if(clothing||color){let desc=brief?(color?'Ropa '+(color==='no se distingue'?'de color desconocido':'de color '+color):clothing):(one||!number?'Lleva ':'Llevan ')+(clothing||'ropa')+(color&&color!=='no se distingue'?' de color '+color:'');if(clothing!=='no se distingue'||color)parts.push(desc+'.');}if(!brief&&$('face').value!==''&&selectedText('face')!=='sin detalle visible')parts.push((one||!number?'Va ':'Van ')+selectedText('face')+'.');const arms={Pistola:'una pistola',Escopeta:'una escopeta',Navaja:'una navaja',Pincho:'un pincho'};if(arms[weapon])parts.push(brief?weapon+' visible.':(one||!number?'Lleva ':'Una de esas personas lleva ')+arms[weapon]+' en la mano.');else if(weapon==='Desarmado')parts.push('Sin armas visibles.');else if(weapon==='No se distingue')parts.push('No se distinguen armas.');if($('travel').value==='foot')parts.push(one||!number?'Va a pie.':'Van a pie.');else if($('travel').value==='unknown'&&!brief)parts.push('No he visto ningún vehículo.');else if($('travel').value==='vehicle'&&vehicle){const col=$('carcolor').value===''?'':selectedText('carcolor'),finish=$('finish').value===''?'':selectedText('finish');parts.push((brief?'Vehículo: ':'El vehículo que veo es un ')+vehicle.name+(col&&col!=='no se distingue'?' de color '+col:'')+(!brief&&finish&&finish!=='sin especificar'?', con acabado '+finish:'')+'.');}if(!brief){document.querySelectorAll('#details input:checked').forEach(c=>parts.push(c.value));const extra=$('extra').value.trim();if(extra)parts.push(extra.replace(/[.!?]+$/,'')+'.');const tone=$('tone').value;if(tone){const openings={n:['¿Hola, policía? Escuchen, por favor:','¡Policía! Necesito avisar de algo:'],s:['Buenas, policía. Quiero informar de lo siguiente:','Policía, les cuento lo que estoy viendo:'],c:['¿Policía? Oigan, miren lo que está pasando:','¡Eh, policía! Escuchen un momento:']};parts.unshift(pick(openings[tone]));parts.push(tone==='n'?'¡VENGAN A ECHAR UN VISTAZO, POR FAVOR!':tone==='c'?'¡Manden a alguien, por favor!':'¿Pueden enviar una patrulla a comprobarlo?');}}$('output').textContent='/entorno '+parts.join(' ');count();$('status').textContent='';}

function count(){$('count').textContent=$('output').textContent.length+' caracteres'}$('form').onsubmit=e=>{e.preventDefault();version++;generate()};$('variant').onclick=()=>{version++;generate()};$('form').addEventListener('change',()=>{const active=$('travel').value==='vehicle';$('garage').hidden=!active;generate()});$('extra').oninput=generate;$('tone').onchange=generate;$('length').onchange=generate;$('output').oninput=count;$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').textContent);$('status').textContent='Copiado. Listo para pegar en el servidor.'}catch{const range=document.createRange();range.selectNodeContents($('output'));const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);$('status').textContent='Texto seleccionado. Pulsa Ctrl+C para copiar.'}};$('reset').onclick=()=>{$('form').reset();number='2';weapon='Pistola';chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);$('carcolor').value='2';vehicle=null;onlyFav=false;$('favfilter').setAttribute('aria-pressed','false');$('favfilter').textContent='☆ Favoritos';$('garage').hidden=false;renderCars();generate()};
fetch('vehicles.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{catalog=data.sort((a,b)=>a.name.localeCompare(b.name));for(const c of [...new Set(catalog.map(v=>v.category))].sort()){const o=document.createElement('option');o.value=c;o.textContent=categories[c]||c;$('category').append(o)}vehicle=null;renderCars();generate()}).catch(()=>{$('catalogstatus').textContent='No se ha podido cargar el catálogo. Recarga la página para reintentar.'});generate();

function renderTravelButtons(){const items=[['vehicle','Seleccionar coche'],['foot','A pie'],['unknown','No se ha visto vehículo']];$('travel-buttons').replaceChildren(...items.map(([value,label])=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-pressed',String($('travel').value===value));b.onclick=()=>{$('travel').value=value;$('garage').hidden=value!=='vehicle';renderTravelButtons();generate()};return b}));}
const resetWithTravel=$('reset').onclick;$('reset').onclick=()=>{resetWithTravel();renderTravelButtons()};renderTravelButtons();


const configFields=['situation','place','clothing','clothcolor','face','travel','carcolor','finish','tone','length','extra'];
for(const id of configFields){const el=$(id);if(el.tagName==='SELECT'){const o=document.createElement('option');o.value='';o.textContent='Sin seleccionar';o.defaultSelected=true;el.prepend(o);}}
function refreshChips(){chips('numbers',['1','2','3','4','5','6','Más de 6'],number,x=>number=x);chips('weapons',['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'],weapon,x=>weapon=x);renderTravelButtons();}
function clearConfig(){number='';weapon='';vehicle=null;for(const id of configFields)$(id).value='';document.querySelectorAll('#details input').forEach(c=>c.checked=false);$('search').value='';$('category').value='';onlyFav=false;$('favfilter').setAttribute('aria-pressed','false');$('favfilter').textContent='☆ Favoritos';$('garage').hidden=true;refreshChips();renderCars();generate();$('status').textContent='';}
$('reset').textContent='Vaciar todo ↻';$('reset').onclick=clearConfig;
let slots=Array(5).fill(null);try{const saved=JSON.parse(localStorage.getItem('entorno-configs-v1')||'null');if(Array.isArray(saved))slots=Array.from({length:5},(_,i)=>saved[i]&&typeof saved[i]==='object'?saved[i]:null);}catch{}
function persistSlots(next){try{localStorage.setItem('entorno-configs-v1',JSON.stringify(next));slots=next;return true}catch{$('slot-status').textContent='No se ha podido guardar. Revisa el almacenamiento del navegador.';return false}}
function snapshot(){return {fields:Object.fromEntries(configFields.map(id=>[id,$(id).value])),number,weapon,vehicleId:vehicle?.id||null,details:[...document.querySelectorAll('#details input:checked')].map(c=>c.value)}}
function loadConfig(data){clearConfig();for(const id of configFields){if(typeof data.fields?.[id]==='string')$(id).value=data.fields[id];}number=['1','2','3','4','5','6','Más de 6'].includes(data.number)?data.number:'';weapon=['Desarmado','Pistola','Escopeta','Navaja','Pincho','No se distingue'].includes(data.weapon)?data.weapon:'';vehicle=catalog.find(c=>c.id===data.vehicleId)||null;document.querySelectorAll('#details input').forEach(c=>c.checked=Array.isArray(data.details)&&data.details.includes(c.value));$('garage').hidden=$('travel').value!=='vehicle';refreshChips();renderCars();generate();}
function renderSlots(){$('slots').replaceChildren(...slots.map((slot,i)=>{const row=document.createElement('div');row.className='slot';const name=document.createElement('input');name.maxLength=40;name.placeholder='Configuración '+(i+1);name.value=slot?.name||'';name.setAttribute('aria-label','Nombre de configuración '+(i+1));const save=document.createElement('button');save.textContent=slot?'Actualizar':'Guardar';save.type='button';save.onclick=()=>{const next=slots.slice();next[i]={name:name.value.trim()||'Configuración '+(i+1),data:snapshot()};if(persistSlots(next)){renderSlots();$('slot-status').textContent='Configuración '+(i+1)+' guardada.'}};const load=document.createElement('button');load.type='button';load.textContent='Cargar';load.disabled=!slot;load.onclick=()=>{loadConfig(slot.data||{});$('slot-status').textContent='Cargada: '+slot.name};const del=document.createElement('button');del.type='button';del.textContent='×';del.setAttribute('aria-label','Borrar configuración '+(i+1));del.disabled=!slot;del.onclick=()=>{const next=slots.slice();next[i]=null;if(persistSlots(next)){renderSlots();$('slot-status').textContent='Espacio '+(i+1)+' vacío.'}};row.append(name,save,load,del);return row}));}
clearConfig();renderSlots();
